  autoState: AUTO.STOPPED, // Start / Pause / Stop
  intervalS: DEFAULT_INTERVAL_S, // how often the automatic update reads, in seconds (15 min to 4 h)
  tz: 'UTC', // the person's IANA time zone (wake-up times are on their clock)
  theme: 'warm',
